<template><section class="space-y-6"><div class="flex items-center justify-between"><h1 class="text-2xl font-semibold">Staff</h1><button class="rounded bg-primary px-4 py-2 text-primary-foreground" @click="showInvite = !showInvite">Invite staff</button></div><form v-if="showInvite" class="grid gap-3 rounded-xl bg-background p-5 shadow md:grid-cols-3" @submit.prevent="invite"><input v-model="form.email" required type="email" placeholder="Email" class="rounded border p-2" /><input v-model="form.name" required placeholder="Name" class="rounded border p-2" /><button class="rounded bg-primary p-2 text-primary-foreground">Send invitation</button><p v-if="message" class="md:col-span-3 text-sm">{{ message }}</p></form><div class="overflow-auto rounded-xl bg-background shadow"><table class="w-full text-left text-sm"><thead><tr class="border-b"><th class="p-4">Name</th><th class="p-4">Email</th><th class="p-4">Status</th><th class="p-4">Permissions</th></tr></thead><tbody><tr v-for="user in users" :key="user.id" class="border-b"><td class="p-4">{{ user.name }}</td><td class="p-4">{{ user.email }}</td><td class="p-4">{{ user.active ? 'Active' : 'Inactive' }}</td><td class="p-4">{{ user.effectivePermissions?.length || 0 }}</td></tr></tbody></table></div></section></template>
<script setup lang="ts">import { onMounted, reactive, ref } from "vue"; import { authHttp } from "@/auth"; const users = ref<any[]>([]); const showInvite = ref(false); const message = ref(""); const form = reactive({ email: "", name: "" }); const load = async () => { const { data } = await authHttp.get("/api/staff/users"); users.value = Array.isArray(data) ? data : data.users || []; }; const invite = async () => { try { const { data } = await authHttp.post("/api/staff/users", { ...form, roleIds: [], grants: [], denials: [] }); message.value = `Invitation token: ${data.invitationToken}`; form.email = ""; form.name = ""; await load(); } catch { message.value = "Unable to create staff account."; } }; onMounted(load);</script>
